// Deploy only configs generated by prepare-hosted-staging.mjs. Existing
// alternative.domains and domains.domains routes are never modified.
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
const dir = path.resolve('.wrangler/hosted');
function run(args) {
  const r = spawnSync(
    process.execPath,
    ['node_modules/wrangler/bin/wrangler.js', ...args],
    {
      stdio: 'inherit',
      env: {
        ...process.env,
        CI: '1',
        WRANGLER_LOG_PATH: path.join(dir, 'logs'),
      },
    },
  );
  if (r.status !== 0) process.exit(r.status ?? 1);
}
for (const name of ['tenant-0', 'tenant-1', 'tenant-2', 'gateway']) {
  const config = path.join(dir, `${name}.jsonc`);
  const cfg = JSON.parse(fs.readFileSync(config, 'utf8'));
  if (!cfg.name.startsWith('domains-staging') || cfg.routes?.length)
    throw Error('Refusing a non-staging deployment');
  if (
    name !== 'gateway' &&
    (cfg.workers_dev !== false || cfg.preview_urls !== false)
  )
    throw Error('Tenant must have no public ingress');
  run([
    'd1',
    'migrations',
    'apply',
    name === 'gateway' ? 'CONTROL_DB' : 'DB',
    '--remote',
    '--config',
    config,
  ]);
  run(['deploy', '--config', config]);
  run([
    'secret',
    'bulk',
    path.join(dir, `${name}-secrets.json`),
    '--config',
    config,
  ]);
}
run([
  'd1',
  'execute',
  'CONTROL_DB',
  '--remote',
  '--config',
  path.join(dir, 'gateway.jsonc'),
  '--file',
  path.join(dir, 'seed.sql'),
]);
console.log(
  'Staging services deployed. Verify signup and isolation before importing founder data.',
);
